const input = $input.first().json;
const body = input.body || input;
const jobId = body.jobId || ('tsd-' + Date.now() + '-' + Math.random().toString(36).substr(2, 8));
const clientName = body.clientName;
let sdrData = body.sdrData || body.sdr;

if (!clientName || !sdrData) throw new Error('Missing required fields: clientName, sdrData');

// ── Field alias normalization ─────────────────────────────────
// SDR workflow may produce section_b_evars / section_b_props / section_b_events
if (!sdrData.evars   && sdrData.section_b_evars)   sdrData.evars   = sdrData.section_b_evars;
if (!sdrData.props   && sdrData.section_b_props)   sdrData.props   = sdrData.section_b_props;
if (!sdrData.events  && sdrData.section_b_events)  sdrData.events  = sdrData.section_b_events;

// Ensure arrays exist (fallback to empty)
if (!sdrData.evars)        sdrData.evars        = [];
if (!sdrData.props)        sdrData.props        = [];
if (!sdrData.events)       sdrData.events       = [];
if (!sdrData.section_a_ootb) sdrData.section_a_ootb = [];
if (!sdrData.data_layer_map) sdrData.data_layer_map = [];

const callbackUrl = body.callbackUrl || null;

console.log('=== TSD Job ===');
console.log('Job ID:', jobId);
console.log('Client:', clientName);
console.log('eVars:', sdrData.evars.length, 'Props:', sdrData.props.length, 'Events:', sdrData.events.length);
console.log('OOTB:', sdrData.section_a_ootb.length, 'DLM:', sdrData.data_layer_map.length);

return [{ json: { jobId, clientName, sdrData, callbackUrl, jobStartedAt: new Date().toISOString() } }];

const input = $('Validate TSD Input').first().json;
const tsdPayload = {
  body: [{
    clientName: input.clientName,
    sdr: input.sdrData
  }]
};
return [{ json: tsdPayload }];

