// ── Merge TSD JS (Part 1) + TSD Doc (Part 2) ─────────────────────────
// Handles both output formats:
//   A) json.output = string (standard Agent node output)
//   B) json.output = object (Structured Output Parser result)
//   C) json itself = the parsed object (Structured Output Parser direct)

function getAgentOutput(nodeName) {
  const nodeJson = $(nodeName).first().json;
  const raw = nodeJson.output;

  // Case A: output is a JSON string — most common
  if (typeof raw === 'string') return raw;

  // Case B: output is an already-parsed object (Structured Output Parser)
  if (raw !== null && raw !== undefined && typeof raw === 'object') {
    return JSON.stringify(raw);
  }

  // Case C: output missing — the parsed fields ARE the json (SOP direct result)
  // Strip internal n8n fields and return remaining as JSON
  const clone = Object.assign({}, nodeJson);
  delete clone.sessionId;
  delete clone.action;
  if (Object.keys(clone).length > 0) return JSON.stringify(clone);

  return '{}';
}

function safeParse(raw) {
  // raw is always a string here (from getAgentOutput)
  try {
    const m = raw.match(/\{[\s\S]*\}/);
    return m ? JSON.parse(m[0]) : JSON.parse(raw);
  } catch(e) {
    console.warn('⚠️ safeParse failed:', e.message, '| snippet:', raw.slice(0, 120));
    return {};
  }
}

const rawJS  = getAgentOutput('TSD JS Agent');
const rawDoc = getAgentOutput('TSD Doc Agent');

console.log('rawJS type:', typeof rawJS,  '| length:', rawJS.length);
console.log('rawDoc type:', typeof rawDoc, '| length:', rawDoc.length);

const part1 = safeParse(rawJS);
const part2 = safeParse(rawDoc);
const clientName = $('Prepare TSD Input').first().json.body?.[0]?.clientName || 'Unknown';

if (!part1.javascript) console.warn('⚠️ TSD JS missing — part1 keys:', Object.keys(part1).join(','));
if (!part2.markdown)   console.warn('⚠️ TSD Doc missing — part2 keys:', Object.keys(part2).join(','));

const merged = {
  output: JSON.stringify({
    clientName,
    javascript:    part1.javascript    || '// TSD JS generation failed',
    markdown:      part2.markdown      || '# TSD Doc generation failed',
    launchPayload: part2.launchPayload || { property_info:{}, extensions:[], rules:[] }
  })
};

console.log('=== Merge TSD Parts ===');
console.log('JS size:',       (part1.javascript    || '').length, 'chars');
console.log('Markdown size:', (part2.markdown      || '').length, 'chars');
console.log('Rules count:',   (part2.launchPayload?.rules || []).length);

return [{ json: merged }];

// Parse TSD Agent output (2-3 files: JavaScript, Markdown, optional Launch Payload)
// input.output is a JSON STRING from Merge TSD Parts — must parse before accessing fields
const input = $input.first().json;

// ── Robust output extraction ─────────────────────────────────────
let tsdOutput;

if (typeof input.output === 'string') {
  // Standard case: Merge TSD Parts returns output as JSON string
  try {
    const m = input.output.match(/\{[\s\S]*\}/);
    tsdOutput = m ? JSON.parse(m[0]) : JSON.parse(input.output);
  } catch(e) {
    throw new Error('Failed to parse Merge TSD Parts output JSON: ' + e.message + ' | snippet: ' + input.output.slice(0, 200));
  }
} else if (input.output && typeof input.output === 'object') {
  // Already an object (e.g. Structured Output Parser result)
  tsdOutput = input.output;
} else {
  // Fallback: input itself may be the TSD data
  tsdOutput = input;
}

// ── Validate required fields ─────────────────────────────────────
const clientName = tsdOutput.clientName || input.clientName;
if (!clientName) {
  throw new Error('TSD output missing clientName field. Keys found: ' + Object.keys(tsdOutput).join(', '));
}

if (!tsdOutput.javascript || !tsdOutput.markdown) {
  const missing = [!tsdOutput.javascript && 'javascript', !tsdOutput.markdown && 'markdown'].filter(Boolean).join(', ');
  throw new Error('TSD output missing required fields: ' + missing + '. Keys found: ' + Object.keys(tsdOutput).join(', '));
}

const hasLaunchPayload = !!tsdOutput.launchPayload;
if (!hasLaunchPayload) {
  console.warn('WARNING: launchPayload not found in TSD output - operating in 2-file mode');
}

const timestamp = new Date().toISOString().replace(/[:.]/g, '-').slice(0, -5);
const jsFilename = clientName + '_adobeDataLayer_' + timestamp + '.js';
const mdFilename = clientName + '_TSD_' + timestamp + '.md';
const launchFilename = clientName + '_LaunchPayload_' + timestamp + '.json';

const launchPayloadStr = typeof tsdOutput.launchPayload === 'string'
  ? tsdOutput.launchPayload
  : JSON.stringify(tsdOutput.launchPayload, null, 2);

console.log('=== Parse TSD Output (' + (hasLaunchPayload ? '3' : '2') + ' Files) ===');
console.log('Client:', clientName);
console.log('JavaScript size:', tsdOutput.javascript.length);
console.log('Markdown size:', tsdOutput.markdown.length);
if (hasLaunchPayload) console.log('Launch Payload size:', launchPayloadStr.length);

return [{
  json: {
    clientName: clientName,
    files: {
      javascript: { filename: jsFilename, content: tsdOutput.javascript, size: tsdOutput.javascript.length, type: 'application/javascript' },
      markdown:   { filename: mdFilename, content: tsdOutput.markdown,   size: tsdOutput.markdown.length,   type: 'text/markdown' },
      ...(hasLaunchPayload && {
        launchPayload: { filename: launchFilename, content: launchPayloadStr, size: launchPayloadStr.length, type: 'application/json' }
      })
    },
    stats: {
      jsLines: tsdOutput.javascript.split('\n').length,
      mdLines: tsdOutput.markdown.split('\n').length,
      ...(hasLaunchPayload && { launchRulesCount: (tsdOutput.launchPayload.rules || []).length }),
      generatedAt: new Date().toISOString()
    }
  }
}];

'use strict';

// ── n8n Input ─────────────────────────────────────────────────────────────────
// Reads DOCX base64 from the upstream "Call DOCX Service" HTTP Request node.
// No require() is needed — the webhook-service handles docx generation.
const svcResult  = $('Call DOCX Service').first().json;
const parsedData = $('Parse TSD Output').first().json;
const clientName = parsedData.clientName || 'Client';

if (!svcResult || !svcResult.success) {
  throw new Error('DOCX service returned failure: ' + (svcResult && svcResult.error || 'unknown error'));
}

const base64       = svcResult.base64;
const docxFilename = svcResult.filename;
const sectionCount = svcResult.sectionCount || 0;

if (!base64) {
  throw new Error('DOCX service response missing base64 field');
}

const manualBinary = {
  data: base64,
  mimeType: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
  fileName: docxFilename,
};

// Use prepareBinaryData if available; fall back to manual base64 object
let binaryData = manualBinary;
try {
  if (this?.helpers?.prepareBinaryData) {
    const buffer = Buffer.from(base64, 'base64');
    binaryData = (await this.helpers.prepareBinaryData(buffer, docxFilename)) || manualBinary;
  }
} catch (e) {
  console.warn('prepareBinaryData failed, using manual base64:', e?.message || e);
}

return [{
  json: { clientName, filename: docxFilename, fileType: 'DOCX', sectionCount },
  binary: { data: binaryData },
}];

// Split files into individual items for Google Drive upload.
// The upstream "Merge DOCX + Folder" node (mode: append) guarantees that BOTH:
//   - Generate TSD DOCX (DOCX binary)
//   - Create Client Folder (Google Drive folder)
// have completed before this node runs — so direct node references are safe.

const parsedData  = $('Parse TSD Output').first().json;
const docxItem    = $('Generate TSD DOCX').first();
const folderItem  = $('Create Client Folder').first();

const folderId    = folderItem.json.id;
const docxBinary  = docxItem.binary?.data;
const docxFilename = docxItem.json?.filename;

if (!folderId) {
  throw new Error('folderId missing — Create Client Folder may have failed');
}

const timestamp = new Date().toISOString().replace(/[:.]/g, '-').slice(0, -5);
const result = [];

// ── JavaScript file ──────────────────────────────────────────────────────────
const jsBase64 = Buffer.from(parsedData.files.javascript.content, 'utf-8').toString('base64');
result.push({
  json: {
    clientName: parsedData.clientName,
    filename:   parsedData.files.javascript.filename,
    fileType:   'JavaScript',
    folderId,
    stats:      parsedData.stats,
  },
  binary: { data: { data: jsBase64, mimeType: 'text/plain; charset=utf-8', fileName: parsedData.files.javascript.filename } }
});

// ── Markdown file ────────────────────────────────────────────────────────────
const mdBase64 = Buffer.from(parsedData.files.markdown.content, 'utf-8').toString('base64');
result.push({
  json: {
    clientName: parsedData.clientName,
    filename:   parsedData.files.markdown.filename,
    fileType:   'Markdown',
    folderId,
    stats:      parsedData.stats,
  },
  binary: { data: { data: mdBase64, mimeType: 'text/plain; charset=utf-8', fileName: parsedData.files.markdown.filename } }
});

// ── TSD DOCX ─────────────────────────────────────────────────────────────────
if (docxBinary && (docxBinary.data || docxBinary.id)) {
  const name = docxFilename || (parsedData.clientName + '_TSD_' + timestamp + '.docx');
  result.push({
    json: {
      clientName: parsedData.clientName,
      filename:   name,
      fileType:   'DOCX',
      folderId,
      stats:      parsedData.stats,
    },
    binary: { data: {
      ...docxBinary,
      mimeType: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
      fileName: name,
    }}
  });
  console.log('✅ TSD DOCX included: ' + name);
} else {
  console.warn('⚠️  TSD DOCX binary not found — skipping DOCX upload');
}

// ── Launch Payload (optional) ────────────────────────────────────────────────
if (parsedData.files?.launchPayload) {
  const launchBase64 = Buffer.from(parsedData.files.launchPayload.content, 'utf-8').toString('base64');
  result.push({
    json: {
      clientName: parsedData.clientName,
      filename:   parsedData.files.launchPayload.filename,
      fileType:   'Launch Payload',
      folderId,
      stats:      parsedData.stats,
    },
    binary: { data: { data: launchBase64, mimeType: 'application/json; charset=utf-8', fileName: parsedData.files.launchPayload.filename } }
  });
} else {
  console.warn('⚠️  launchPayload not found — uploading without it');
}

return result;

// Collect all uploaded file info from Upload to Google Drive.
// $('Make TSD File Public') outputs permission data (no file metadata),
// so we reference $('Upload to Google Drive').all() for actual file info.
const items      = $('Upload to Google Drive').all();
const clientName = $('Parse TSD Output').first().json.clientName
                   || (items[0]?.json?.name ?? '').split('_')[0];

console.log('=== TSD Files Uploaded to Google Drive ===');
console.log('Client:', clientName, '| Files:', items.length);

const uploadedFiles = items.map(item => ({
  fileId:         item.json.id,
  fileName:       item.json.name,
  mimeType:       item.json.mimeType,
  webViewLink:    item.json.webViewLink,
  webContentLink: item.json.webContentLink,
  createdTime:    item.json.createdTime,
}));

const fileTypes = {
  javascript:    uploadedFiles.find(f => f.fileName && f.fileName.match(/\.(js|txt)$/) && !f.fileName.endsWith('.docx')),
  markdown:      uploadedFiles.find(f => f.fileName && f.fileName.endsWith('.md')),
  docx:          uploadedFiles.find(f => f.fileName && f.fileName.endsWith('.docx')),
  launchPayload: uploadedFiles.find(f => f.fileName && f.fileName.toLowerCase().includes('launchpayload')),
};

const hasDocx          = !!fileTypes.docx;
const hasLaunchPayload = !!fileTypes.launchPayload;

// Google Doc (triggered in parallel — may have run; safe fallback)
let googleDocs = null;
try {
  const gdocResult = $('Create TSD Google Doc').first();
  const gdocId = gdocResult?.json?.id || gdocResult?.json?.documentId || null;
  if (gdocId) {
    googleDocs = {
      id:   gdocId,
      url:  `https://docs.google.com/document/d/${gdocId}/edit`,
      name: gdocResult?.json?.name || '',
    };
    console.log('Google Doc:', googleDocs.url);
  }
} catch (e) {
  console.warn('⚠️  Create TSD Google Doc not available:', e.message);
}

// Client folder name: {clientName}_{YYYYMMDDHHMMSS}
const folderNode = $('Create Client Folder').first();
const folderName = folderNode?.json?.name || `${clientName} (unknown timestamp)`;

uploadedFiles.forEach(f => console.log(`  - ${f.fileName} (${f.fileId})`));
if (!hasLaunchPayload) console.warn('⚠️  Launch Payload not found');
if (!hasDocx)          console.warn('⚠️  DOCX not found — generate-tsd may have failed');

const fileTypesList = ['JavaScript', 'Markdown',
  hasDocx          ? 'DOCX'           : null,
  hasLaunchPayload ? 'Launch Payload' : null,
].filter(Boolean).join(', ');

return [{
  json: {
    success:     true,
    clientName,
    googleDrive: {
      folder:    `TSD/${folderName}`,
      files:     uploadedFiles,
      fileTypes,
    },
    googleDocs,
    totalFiles:       items.length,
    hasDocx,
    hasLaunchPayload,
    message: `Successfully uploaded ${items.length} files (${fileTypesList}) to Google Drive`,
  },
}];
